import json
import requests
import os
import math

class ZohoSheetUploader:
    def __init__(self, auth_token, base_url="https://sheet.zoho.in/api/v2"):
        self.auth_token = auth_token
        self.base_url = base_url
        self.headers = {
            "Authorization": f"Zoho-oauthtoken {self.auth_token}"
        }

    def create_workbook(self, workbook_name):
        url = f"{self.base_url}/create"
        data = {
            "method": "workbook.create",
            "workbook_name": workbook_name
        }
        response = requests.post(url, headers=self.headers, data=data)
        response.raise_for_status()
        return response.json()

    def rename_worksheet(self, resource_id, old_name, new_name):
        url = f"{self.base_url}/{resource_id}"
        data = {
            "method": "worksheet.rename",
            "old_name": old_name,
            "new_name": new_name
        }
        response = requests.post(url, headers=self.headers, data=data)
        response.raise_for_status()
        return response.json()

    def insert_worksheet(self, resource_id, worksheet_name):
        url = f"{self.base_url}/{resource_id}"
        data = {
            "method": "worksheet.insert",
            "worksheet_name": worksheet_name
        }
        response = requests.post(url, headers=self.headers, data=data)
        response.raise_for_status()
        return response.json()

    def set_cells_content(self, resource_id, cell_data):
        url = f"{self.base_url}/{resource_id}"
        data = {
            "method": "cells.content.set",
            "data": json.dumps(cell_data)
        }
        response = requests.post(url, headers=self.headers, data=data)
        response.raise_for_status()
        return response.json()

    def _parse_column(self, col_key):
        """Parse 'col_X' into an integer."""
        if col_key.startswith('col_'):
            try:
                return int(col_key.replace('col_', ''))
            except ValueError:
                return None
        return None

    def chunk_list(self, lst, chunk_size):
        """Yield successive n-sized chunks from lst."""
        for i in range(0, len(lst), chunk_size):
            yield lst[i:i + chunk_size]

    def upload_data(self, workbook_name, data):
        # 1. Create workbook
        wb_res = self.create_workbook(workbook_name)
        if "resource_id" not in wb_res:
            raise Exception(f"Failed to create workbook: {wb_res}")
        resource_id = wb_res["resource_id"]

        default_sheet_name = wb_res.get("worksheet_name", "Sheet1")

        sheet_names = list(data.keys())
        if not sheet_names:
            return resource_id

        first_sheet = sheet_names[0]

        # 2. Rename first sheet
        try:
            self.rename_worksheet(resource_id, default_sheet_name, first_sheet)
        except Exception as e:
            print(f"Error renaming first sheet: {e}")

        # 3. Create remaining sheets
        for sheet_name in sheet_names[1:]:
            try:
                self.insert_worksheet(resource_id, sheet_name)
            except Exception as e:
                print(f"Error creating sheet '{sheet_name}': {e}")

        # 4. Set cells content for each sheet
        for sheet_name, rows in data.items():
            cell_updates = []
            for row_data in rows:
                if 'row_index' not in row_data:
                    continue
                row_index = row_data['row_index']
                for key, val in row_data.items():
                    col_index = self._parse_column(key)
                    if col_index is not None:
                        cell_updates.append({
                            "worksheet_name": sheet_name,
                            "content": val,
                            "row": row_index,
                            "column": col_index
                        })

            # The API allows a max of 50 cells per call for cells.content.set
            for chunk in self.chunk_list(cell_updates, 50):
                try:
                    self.set_cells_content(resource_id, chunk)
                except Exception as e:
                    print(f"Error setting cells chunk in sheet '{sheet_name}': {e}")

        return resource_id

